class Solution {
    fun numMatchingSubseq(s:String,words:Array<String>):Int{
        val buckets=Array(26){
            java.util.ArrayDeque<IntArray>()
        };
        for(i in words.indices)buckets[words[i][0]-'a'].addLast(intArrayOf(i,0));
        var answer=0;
        for(c in s){
            val queue=buckets[c-'a'];
            repeat(queue.size){
                val state=queue.removeFirst();
                state[1]++;
                if(state[1]==words[state[0]].length)answer++ else buckets[words[state[0]][state[1]]-'a'].addLast(state)
            }
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int numMatchingSubseq(string s,vector<string>& words){
        vector<queue<pair<int,int>>> buckets(26);
        for(int i=0;i<(int)words.size();++i)buckets[words[i][0]-'a'].push({
            i,0
        });
        int answer=0;
        for(char c:s){
            auto& pending=buckets[c-'a'];
            int size=pending.size();
            while(size--){
                auto [word,position]=pending.front();
                pending.pop();
                ++position;
                if(position==(int)words[word].size())++answer;
                else buckets[words[word][position]-'a'].push({
                    word,position
                });
            }
        }
        return answer;
    }
};
